/** 一次性调用把 system + user 合成单条 prompt（inMemory 会话无独立 system 通道时的简化） */
function buildSingleTurn(systemPrompt: string, userPrompt: string): string {
  return `${systemPrompt}\n\n---\n\n${userPrompt}`;
