// ── 题目与作答 ──────────────────────────────────────────────
export type QuestionType = 'single' | 'multiple' | 'boolean';

/** 作答/正确答案的取值：单选=选项 index；多选=index 数组；判断=布尔 */
export type AnswerValue = number | number[] | boolean;

