export interface Question {
  id: string;
  bankId: string;
  type: QuestionType;
  stem: string;
  options: string[];
  answer: AnswerValue;
  explanation?: string;
  tags?: string[];
  source?: QuestionSource;
  createdAt: number;
}

/** 导入草稿：尚未入库、无 id/bankId */
export type QuestionDraft = Omit<Question, 'id' | 'bankId' | 'createdAt'>;

export interface Attempt {
  id: string;
  questionId: string;
  userAnswer: AnswerValue;
  isCorrect: boolean;
  answeredAt: number;
}

export interface Bank {
  id: string;
  name: string;
  createdAt: number;
}

/** v2 题库管理：列表附带题目数 */
export interface BankWithCount extends Bank {
  questionCount: number;
}

// ── v2：题库/题目管理 API 契约 ──────────────────────
export interface CreateBankRequest {
  name: string;
}
export interface RenameBankRequest {
  name: string;
}
/** 新增/编辑单题的载荷（等同一条草稿） */
export type QuestionUpsert = QuestionDraft;

export type MoveCopyOp = 'move' | 'copy';
export interface MoveCopyRequest {
  questionIds: string[];
  targetBankId: string;
  op: MoveCopyOp;
}
export type TagApplyMode = 'add' | 'replace';
export interface ApplyTagsRequest {
  questionIds: string[];
  tags: string[];
  mode: TagApplyMode;
}
/** 批量操作的通用回显：实际影响条数 */
export interface AffectedCountResponse {
  affected: number;
}

// ── 判分 API 契约 ───────────────────────────────────────────
export interface GradeRequest {
  questionId: string;
  userAnswer: AnswerValue;
}

/** attemptId = 新落库 attempt 的 id，供 tutor/explain 关联作答（评审 #4） */
export interface GradeResponse {
  attemptId: string;
  isCorrect: boolean;
  correctAnswer: AnswerValue;
}

// ── 导入 API 契约 ───────────────────────────────────────────
export interface ParseTextRequest {
  text: string;
}
export interface ParseResult {
  questions: QuestionDraft[];
}
export interface ImportCommitRequest {
  bankId?: string;
  bankName?: string;
  questions: QuestionDraft[];
}
export interface ImportCommitResponse {
  bankId: string;
  count: number;
}

